/* ===== SERVICE PROVIDER DASHBOARD ===== */
const sv=()=>svc(S.prov.sid);
const sEnq=()=>D().enq.filter(e=>e.sid===ownerId());
const EST={new:['New','info'],contacted:['Contacted','warn'],converted:['Converted','ok'],closed:['Closed','neu']};
const comingSoon=()=>`<div class="card pad stack" style="border-style:dashed"><div class="row"><span class="badge neu">${t('Coming soon')}</span><b>${t('Booking, quotations & payments')}</b></div><p class="small t2">${t('Enquiries are the only flow today. Booking slots, quotations and online payment are designed to plug in here later.')}</p>${toggle('booking',D().cfg.flags.booking,'Preview booking (feature flag, off)','tg')}</div>`;
V.shome=()=>{const s=sv(),en=sEnq();return `<div class="stack-lg">${gateNote('provider')}<div class="row between wrap-r"><div><h1>${t('Namaste')}, ${esc(nm(s.name))}</h1><div class="small muted">${fdate(Date.now())}</div></div>${apBadge(s.status)}</div>${en.filter(e=>e.status==='new').length&&canAct(MYROLE())?`<a class="alert warn" href="#${RT('senq')}" style="animation:pulse 1.6s infinite">${ic('bell',20)}<div><b>${en.filter(e=>e.status==='new').length} ${t('new enquiries')}</b> · ${t('Reply soon for better conversion')}</div></a>`:''}
 <div class="grid g3" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${kpi('Profile views',series(s.id,1,240,80)[0],'6%')}${kpi('Enquiries (30d)',en.length+11,'3')}${kpi('Converted',en.filter(e=>e.status==='converted').length+2,'')}${kpi('Rating',s.rating.toFixed(1),'')}</div><div class="cols2 eq"><div class="card pad stack"><h3>${t('Enquiries, last 7 days')}</h3>${barChart(series(s.id,7,1,5),lastDays(7))}</div><div class="card pad stack"><h3>${t('Latest enquiries')}</h3>${en.slice(0,3).map(e=>`<a class="row between" href="#${RT('senq')}-${e.id}"><span><b>${esc(e.name)}</b><span class="small t2" style="display:block">${esc(e.msg).slice(0,44)}</span></span><span class="badge ${EST[e.status][1]}">${t(EST[e.status][0])}</span></a>`).join('')||`<span class="muted small">${t('No enquiries yet')}</span>`}<a class="btn o sm" href="#${RT('senq')}">${t('Open inbox')}</a></div></div>${comingSoon()}</div>`};
V.senq=arg=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());if(arg)return senqDetail(arg);const f=UI.sef||'all',q=(UI.seq||'').toLowerCase();const l=sEnq().filter(e=>(f==='all'||e.status===f)&&(!q||(e.name+e.msg).toLowerCase().includes(q)));
 return `<div class="stack"><h1>${t('Enquiries')}</h1><div class="chips">${[['all','All'],...Object.entries(EST).map(([k,v])=>[k,v[0]])].map(([k,l])=>`<button class="chip ${f===k?'on':''}" data-act="sef" data-v="${k}">${t(l)} (${k==='all'?sEnq().length:sEnq().filter(e=>e.status===k).length})</button>`).join('')}</div><div class="searchbar">${ic('search',18)}<input data-in="seq" value="${esc(UI.seq||'')}" placeholder="${t('Search name or message')}" aria-label="${t('Search')}"></div><div id="enqlist">${enqList(l)}</div></div>`};
const enqList=l=>l.length?`<div class="stack">${l.map(e=>`<a class="card pad row hover" href="#${RT('senq')}-${e.id}"><div class="art mini" style="--h:${(e.name.charCodeAt(0)*9)%360};border-radius:50%">${esc(e.name[0])}</div><div class="grow"><b>${esc(e.name)}</b><div class="small t2">${esc(e.msg).slice(0,70)}</div><div class="xs muted">${ago(e.ts)} · ${t('Preferred')}: ${esc(e.date)}</div></div><span class="badge ${EST[e.status][1]}">${t(EST[e.status][0])}</span></a>`).join('')}</div>`:empty('📭','No enquiries','Enquiries from customers will appear here.');
A.sef=el=>{UI.sef=el.dataset.v;render(true)};INP.seq=v=>{UI.seq=v;const q=v.toLowerCase(),f=UI.sef||'all';$('#enqlist').innerHTML=enqList(sEnq().filter(e=>(f==='all'||e.status===f)&&(!q||(e.name+e.msg).toLowerCase().includes(q))))};
function senqDetail(id){const e=D().enq.find(x=>x.id===id);if(!e||e.sid!==ownerId())return V.nf();return `<div class="stack-lg"><a class="btn t sm" href="#${RT('senq')}" style="justify-self:start">${ic('cl',16)} ${t('Inbox')}</a><div class="row between wrap-r"><h1>${esc(e.name)}</h1><span class="badge ${EST[e.status][1]}">${t(EST[e.status][0])}</span></div><div class="card pad stack"><p>${esc(e.msg)}</p><dl class="kv"><dt>${t('Phone')}</dt><dd>+91 ${esc(e.phone)}</dd><dt>${t('Preferred date')}</dt><dd>${esc(e.date)}</dd><dt>${t('Received')}</dt><dd>${fdt(e.ts)}</dd></dl><div class="grid g2"><a class="btn p" href="${telH(e.phone)}" data-act="econtact" data-id="${id}">${ic('phone',18)} ${t('Call')}</a><a class="btn s" target="_blank" rel="noopener" href="${waH(e.phone,'Hello '+e.name+', thanks for your enquiry on ApnaTown.')}" data-act="econtact" data-id="${id}">${ic('chat',18)} ${t('Reply on WhatsApp')}</a></div></div><div class="card pad stack"><h3>${t('Update status')}</h3><div class="chips">${Object.entries(EST).map(([k,v])=>`<button class="chip ${e.status===k?'on':''}" data-act="est" data-id="${id}" data-v="${k}">${t(v[0])}</button>`).join('')}</div></div></div>`}
A.est=el=>{D().enq.find(x=>x.id===el.dataset.id).status=el.dataset.v;save();render(true);toast(t('Status updated'))};A.econtact=el=>{const e=D().enq.find(x=>x.id===el.dataset.id);if(e.status==='new'){e.status='contacted';save()}};
V.sprofile=()=>{if(!canAct(MYROLE())&&sv().status!=='pending')return lockedMsg(MYROLE());afterProfile(sv());const s=sv();return `<div class="stack"><h1>${t('Profile')}</h1>${gateNote('provider')}<div class="cols2"><div>${profileForm(s,true)}</div><div class="stack" style="position:sticky;top:76px"><div class="lbl">${t('Live preview')}</div>${profileHead(s,true)}${svcCard(s,true)}</div></div></div>`};
F.sprof=d=>saveProfile(sv(),d,true);
V.sreviews=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const l=D().reviews.filter(r=>r.tid===S.prov.sid);return `<div class="stack"><h1>${t('Ratings & reviews')}</h1><div class="card pad">${ratingBreak(l.filter(r=>r.status==='published'))}</div>${l.map(r=>`<div class="stack" style="gap:6px">${revCard(r,'none')}<div class="row"><button class="btn o sm" data-act="vreply" data-id="${r.id}">${r.reply?t('Edit reply'):t('Reply')}</button><button class="btn g sm" data-act="vreport" data-id="${r.id}">${ic('flag',14)} ${t('Report abusive')}</button></div></div>`).join('')||empty('⭐','No reviews yet','Reviews appear after customers rate you.')}</div>`};
V.sqr=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const s=sv(),u=shareUrl('svc-'+s.id);return `<div class="stack"><h1>${t('QR code & share link')}</h1><div class="poster" style="max-width:360px;margin:auto"><div style="font-size:2rem">${s.emoji}</div><h2>${esc(nm(s.name))}</h2><div class="t2">${t('Scan to send an enquiry')}</div>${qrSvg(u,s.emoji)}<b>Apna<span style="color:var(--primary)">Town</span>.in</b></div><div class="row noprint" style="max-width:360px;margin:auto;width:100%"><button class="btn p grow" onclick="window.print()">${ic('print',18)} ${t('Print')}</button><button class="btn g grow" data-act="copy" data-v="${esc(u)}">${ic('copy',18)} ${t('Copy link')}</button><button class="btn s grow" data-act="share" data-id="${s.id}">${ic('share',18)}</button></div></div>`};
V.snotif=()=>{const l=D().notifs.provider;return `<div class="stack"><div class="row between"><h1>${t('Notifications')}</h1><button class="btn t sm" data-act="readAll" data-k="provider">${t('Mark all read')}</button></div>${l.length?l.map(notifCard).join(''):empty('🔔','All caught up','New alerts will show here.')}</div>`};
V.sanalytics=()=>{if(!canAct(MYROLE()))return lockedMsg(MYROLE());const s=sv(),en=sEnq();return `<div class="stack-lg"><h1>${t('Analytics')}</h1><div class="grid g3">${kpi('Profile views (30d)',series(s.id,1,820,200)[0],'11%')}${kpi('Enquiries (30d)',en.length+11,'4%')}${kpi('Conversion',Math.round((en.filter(e=>e.status==='converted').length+2)/(en.length+11)*100)+'%','')}</div><div class="card pad stack"><h3>${t('Views vs enquiries')}</h3>${barChart(series(s.id,10,40,60),Array.from({length:10},(_,i)=>'D'+(i+1)))}</div><div class="card pad row between"><span>${t('Enquiry status mix')}</span>${donut(Object.keys(EST).map((k,i)=>[k,en.filter(e=>e.status===k).length,['var(--info)','var(--warning)','var(--success)','var(--muted)'][i]]))}</div></div>`};
V.saccount=()=>{const s=sv();return `<div class="stack"><h1>${t('Account settings')}</h1><form data-form="sowner" class="card pad stack">${field('Owner name','owner',s.owner||'Suresh Verma',{req:1})}${field('Mobile (login)','phone',s.phone,{type:'tel'})}<button class="btn p">${t('Save')}</button></form><div class="card pad stack"><h3>${t('Security')}</h3>${toggle('otp2',true,'Login with OTP','tg')}</div><div class="card pad row between"><span>${ic('globe',18)} ${t('Language')}</span><button class="btn g sm" data-act="lang">${S.lang==='en'?'हिन्दी':'English'}</button></div><a class="btn g" href="#help">${ic('info',18)} ${t('Help & support')}</a></div>`};
F.sowner=d=>{sv().owner=d.owner;save();toast(t('Saved'))};
/* ===== RIDER ===== */
const rd=()=>rider(S.rider.rid);
const myJobs=()=>D().jobs.filter(j=>j.riderId===S.rider.rid);
const activeJob=()=>myJobs().find(j=>!['delivered','failed'].includes(j.status));
const reqJobs=()=>D().jobs.filter(j=>j.status==='requested'&&!j.riderId&&!(j.rejected||[]).includes(S.rider.rid));
const RJ=['accepted','reachedShop','pickedUp','reachedDrop','delivered'];
V.rhome=()=>{const r=rd(),aj=activeJob(),done=myJobs().filter(j=>j.status==='delivered'&&Date.now()-j.ts<DAY),earn=done.reduce((a,j)=>a+j.earn,0);
 return `<div class="stack-lg">${gateNote('rider')}<div class="row between wrap-r"><div><h1>${t('Namaste')}, ${esc(r.name)}</h1><div class="small muted">${esc(r.vehicle)}</div></div>${apBadge(r.status)}</div>
 <div class="card pad row between" style="${r.online&&r.status==='approved'?'border-color:var(--success)':''}"><div><b>${r.online?t('You are online'):t('You are offline')}</b><div class="small t2">${r.online?t('You will get delivery requests nearby.'):t('Go online to receive requests.')}</div></div><span class="toggle"><input type="checkbox" ${r.online?'checked':''} ${r.status==='approved'?'':'disabled'} data-chg="ronline" aria-label="${t('Online')}"><span></span></span></div>
 <div class="grid g3">${kpi('Deliveries today',done.length,'')}${kpi('Earned today',inr(earn),'')}${kpi('Rating',r.rating.toFixed(1),'')}</div>
 ${aj?`<a class="card pad stack hover" href="#ractive" style="border-color:var(--primary)"><div class="row between"><b>${t('Active delivery')}</b><span class="badge solid">${t(jobLabel(aj.status))}</span></div><div class="small t2">${esc(nm(biz(order(aj.oid).bid).name))} → ${esc(order(aj.oid).addr||'')}</div><span class="btn p sm" style="justify-self:start">${t('Continue')}</span></a>`:r.online&&r.status==='approved'?(reqJobs().length?`<a class="alert warn" href="#rreq" style="animation:pulse 1.6s infinite">${ic('bike',20)}<div><b>${reqJobs().length} ${t('new delivery request(s)')}</b></div></a>`:`<div class="state" style="padding:20px">${empty('🛵','Waiting for requests','Stay online. New deliveries will appear here.')}</div>`):''}</div>`};
CH.ronline=el=>{rd().online=el.checked;save();render(true);toast(el.checked?t('You are online'):t('You are offline'),'bike')};
const jobLabel=s=>({requested:'Requested',accepted:'Heading to shop',reachedShop:'At shop',pickedUp:'Picked up',reachedDrop:'At drop',delivered:'Delivered',failed:'Failed'})[s]||s;
V.rreq=()=>{if(!canAct('rider'))return lockedMsg('rider');if(activeJob())return `<div class="stack"><h1>${t('Requests')}</h1>${alertBox('info',t('Finish your active delivery first.'))}<a class="btn p" href="#ractive">${t('Open active delivery')}</a></div>`;const l=reqJobs();
 if(l.length)post.push(()=>{clearInterval(UI.reqT);UI.reqT=setInterval(()=>{const els=$$('[data-cd]');if(!els.length||cur().name!=='rreq')return clearInterval(UI.reqT);els.forEach(el=>{const s=Math.max(0,Math.ceil((+el.dataset.cd-Date.now())/1000));el.textContent=s?s+'s':t('Expired');if(!s){const b=el.closest('.card').querySelector('[data-act=jacc]');if(b)b.disabled=true}})},500)});
 return `<div class="stack"><h1>${t('Delivery requests')}</h1>${!rd().online?alertBox('warn',t('You are offline. Go online to accept deliveries.')):''}${l.length?l.map(j=>{const o=order(j.oid),b=biz(o.bid);j.shown=j.shown||Date.now();return `<div class="card pad stack"><div class="row between"><b>${esc(nm(b.name))}</b><span class="badge warn">${ic('clock',13)} <span data-cd="${j.shown+60000}">60s</span></span></div><div class="small t2">${ic('pin',14)} ${t('Pickup')}: ${esc(b.addr)}<br>${ic('pin',14)} ${t('Drop')}: ${esc(o.addr)}</div><div class="grid g3 center"><div><b>${j.dist} km</b><div class="xs muted">${t('Distance')}</div></div><div><b>${o.items.length}</b><div class="xs muted">${t('Items')}</div></div><div><b style="color:var(--success)">${inr(j.earn)}</b><div class="xs muted">${t('You earn')}</div></div></div><div class="row"><button class="btn g grow" data-act="jrej" data-id="${j.id}">${t('Reject')}</button><button class="btn p grow" data-act="jacc" data-id="${j.id}" ${rd().online?'':'disabled'}>${t('Accept')}</button></div></div>`}).join(''):empty('🛵','No requests right now','New deliveries will appear here.')}</div>`};
A.jacc=el=>{const j=D().jobs.find(x=>x.id===el.dataset.id),o=order(j.oid);if(j.riderId){toast(t('Already taken'),'alert');return}j.riderId=S.rider.rid;j.status='accepted';o.riderId=S.rider.rid;notify('vendor','Rider assigned for '+o.id,rd().name+' is coming to the shop','vorder-'+o.id,'job');if(o.uid==='u1')notify('cust','Rider assigned',rd().name+' will deliver your order '+o.id,'order-'+o.id,'order');save();go('ractive');toast(t('Delivery accepted'),'check')};
A.jrej=el=>{const j=D().jobs.find(x=>x.id===el.dataset.id);j.rejected=[...(j.rejected||[]),S.rider.rid];save();render(true);toast(t('Request rejected'))};
V.ractive=()=>{if(!canAct('rider'))return lockedMsg('rider');const j=activeJob();if(!j)return `<div class="stack"><h1>${t('Active delivery')}</h1>${empty('🛵','No active delivery','Accept a request to start.','<a class="btn p" href="#rreq">'+t('See requests')+'</a>')}</div>`;
 const o=order(j.oid),b=biz(o.bid),pos=o.addrPos||addrPos(),idx=RJ.indexOf(j.status),me=j.status==='accepted'?{lat:b.lat+(CENTER.lat-b.lat)*.3,lng:b.lng+(CENTER.lng-b.lng)*.3}:j.status==='pickedUp'?{lat:b.lat+(pos.lat-b.lat)*.45,lng:b.lng+(pos.lng-b.lng)*.45}:j.status==='reachedDrop'?pos:b;const toDrop=km(me,pos),toShop=km(me,b);
 const step=(k,l)=>{const i=RJ.indexOf(k);return `<li class="s ${idx>=i?'done':''} ${idx===i-1?'cur':''}"><span class="n">${idx>=i?'✓':i+1}</span><div><b>${t(l)}</b></div></li>`};
 let act='';if(j.status==='accepted')act=`<button class="btn p block" data-act="jstep" data-id="${j.id}" data-to="reachedShop">${t('I reached the shop')}</button>`;
 else if(j.status==='reachedShop')act=`<div class="card pad stack"><h3>${t('Check the items')}</h3>${o.items.map((i,k)=>`<label class="check"><input type="checkbox" class="chk" style="accent-color:var(--primary)" data-chg="itemchk"> ${i.emoji} ${esc(nm(i.name))} × ${i.qty}</label>`).join('')}</div><button class="btn p block" id="pickbtn" data-act="jstep" data-id="${j.id}" data-to="pickedUp" disabled>${t('Picked up')}</button>`;
 else if(j.status==='pickedUp')act=`<button class="btn p block" data-act="jstep" data-id="${j.id}" data-to="reachedDrop">${t('I reached the drop')}</button>`;
 else if(j.status==='reachedDrop')act=`<form data-form="jotp" class="stack"><input type="hidden" name="id" value="${j.id}">${field('Customer OTP','otp','',{req:1,im:'numeric',pattern:'[0-9]{4}',hint:'Ask the customer for the 4-digit OTP'})}${o.pay.status==='pending'?alertBox('warn',`<b>${t('Collect cash')}: ${inr(orderTotal(o))}</b>`,'rupee'):''}<button class="btn p block">${t('Complete delivery')}</button></form>`;
 return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Active delivery')}</h1><span class="badge solid">${t(jobLabel(j.status))}</span></div>
 <div class="cols2"><div class="stack">${mapSvg('rmap',[{id:'shop',name:b.name,emoji:'🏪',lat:b.lat,lng:b.lng},{id:'drop',name:{en:'Drop'},emoji:'🏠',lat:pos.lat,lng:pos.lng}],{me,center:{lat:(b.lat+pos.lat)/2,lng:(b.lng+pos.lng)/2}})}<div class="grid g2 center"><div class="card pad"><b>${toShop.toFixed(1)} km</b><div class="xs muted">${t('to shop')}</div></div><div class="card pad"><b>${toDrop.toFixed(1)} km</b><div class="xs muted">${t('to drop')}</div></div></div>
 <a class="btn o block" target="_blank" rel="noopener" href="${mapsDir(['accepted','reachedShop'].includes(j.status)?b:pos)}">${ic('nav',18)} ${t('Navigate')}</a>${act}
 <button class="btn t" data-act="jfail" data-id="${j.id}" style="color:var(--error)">${t('Can’t complete? Report an issue')}</button></div>
 <div class="stack"><div class="card pad"><ol class="tl" style="list-style:none;padding:0;margin:0">${step('accepted','Accepted')}${step('reachedShop','Reached shop')}${step('pickedUp','Picked up')}${step('reachedDrop','Reached drop')}${step('delivered','Delivered')}</ol></div><div class="card pad stack"><h3>${t('Order')} ${o.id}</h3><dl class="kv"><dt>${t('Pickup')}</dt><dd>${esc(nm(b.name))}</dd><dt>${t('Drop')}</dt><dd>${esc(o.addr)}</dd><dt>${t('Customer')}</dt><dd>${esc(o.cust)}</dd><dt>${t('You earn')}</dt><dd><b>${inr(j.earn)}</b></dd></dl><a class="btn g" href="tel:+919876500000">${ic('phone',18)} ${t('Call customer (masked)')}</a><div class="xs muted">${t('Your number and the customer’s number stay hidden. Calls go through ApnaTown.')}</div></div></div></div></div>`};
CH.itemchk=()=>{const all=$$('.chk');$('#pickbtn').disabled=!all.every(c=>c.checked)};
A.jstep=el=>{const j=D().jobs.find(x=>x.id===el.dataset.id),o=order(j.oid);j.status=el.dataset.to;if(j.status==='reachedShop')notify('vendor','Rider reached shop',o.id,'vorder-'+o.id,'job');if(j.status==='pickedUp')setStatus(o,'out');save();render(true)};
F.jotp=d=>{const j=D().jobs.find(x=>x.id===d.id),o=order(j.oid);if(d.otp!==o.otp){toast(t('Wrong OTP. Ask the customer again.'),'alert');return}j.status='delivered';j.ts=Date.now();if(o.pay.status==='pending')o.pay.status='paid';setStatus(o,'delivered');rd().rc++;save();sheet(`<div class="state"><div class="ill" style="background:var(--success-soft)">🎉</div><h3>${t('Delivered!')}</h3><p>${t('You earned')} <b>${inr(j.earn)}</b></p><a class="btn p" href="#rhome" data-act="closeSheet">${t('Back to home')}</a></div>`)};
A.jfail=el=>sheet(`<h3>${t('Report an issue')}</h3><form data-form="jfail" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${el.dataset.id}">${field('Reason','reason','',{type:'select',opts:[['Customer unreachable','Customer unreachable'],['Wrong address','Wrong address'],['Customer cancelled','Customer cancelled'],['Vehicle problem','Vehicle problem']]})}<button class="btn d">${t('Mark delivery failed')}</button></form>`);
F.jfail=d=>{const j=D().jobs.find(x=>x.id===d.id),o=order(j.oid);j.status='failed';o.cancel={by:'rider',reason:d.reason};if(o.pay.status==='paid')o.refund={status:'requested',steps:[['requested',Date.now()]]};o.case={type:'Delivery failed',status:'open',notes:[d.reason]};setStatus(o,'cancelled');notify('admin','Delivery failed '+o.id,d.reason,'aorder-'+o.id,'order');notify('vendor','Delivery failed '+o.id,d.reason,'vorder-'+o.id,'order');save();closeSheet();go('rhome');toast(t('Reported. Admin has been notified.'))};
V.rhistory=()=>{if(!canAct('rider'))return lockedMsg('rider');const f=UI.rh||'all',lim=f==='today'?DAY:f==='week'?7*DAY:1e15,l=myJobs().filter(j=>['delivered','failed'].includes(j.status)&&Date.now()-j.ts<lim);return `<div class="stack"><h1>${t('Delivery history')}</h1><div class="chips">${[['all','All'],['today','Today'],['week','This week']].map(([k,lb])=>`<button class="chip ${f===k?'on':''}" data-act="rhf" data-v="${k}">${t(lb)}</button>`).join('')}</div>${tbl(['Order','Shop','Distance','Earned','Status','When'],l.map(j=>{const o=order(j.oid);return [`<a href="#" data-act="jdetail" data-id="${j.id}" style="color:var(--primary)">${j.oid}</a>`,esc(nm(biz(o.bid).name)),j.dist+' km',j.status==='delivered'?inr(j.earn):'-',`<span class="badge ${j.status==='delivered'?'ok':'bad'}">${t(jobLabel(j.status))}</span>`,fdt(j.ts)]}))}</div>`};
A.rhf=el=>{UI.rh=el.dataset.v;render(true)};
A.jdetail=el=>{const j=D().jobs.find(x=>x.id===el.dataset.id),o=order(j.oid);sheet(`<h3>${t('Delivery')} ${o.id}</h3><dl class="kv" style="margin-top:10px"><dt>${t('Shop')}</dt><dd>${esc(nm(biz(o.bid).name))}</dd><dt>${t('Drop')}</dt><dd>${esc(o.addr)}</dd><dt>${t('Distance')}</dt><dd>${j.dist} km</dd><dt>${t('Base')}</dt><dd>${inr(D().cfg.riderBase)}</dd><dt>${t('Distance pay')}</dt><dd>${inr(Math.round(D().cfg.riderPerKm*j.dist))}</dd><dt><b>${t('Total earned')}</b></dt><dd><b>${inr(j.earn)}</b></dd></dl>`)};
V.rearn=()=>{if(!canAct('rider'))return lockedMsg('rider');const l=myJobs().filter(j=>j.status==='delivered'),tot=l.reduce((a,j)=>a+j.earn,0),wk=l.filter(j=>Date.now()-j.ts<7*DAY).reduce((a,j)=>a+j.earn,0);
 return `<div class="stack-lg"><h1>${t('Earnings')}</h1><div class="grid g3">${kpi('Today',inr(l.filter(j=>Date.now()-j.ts<DAY).reduce((a,j)=>a+j.earn,0)),'')}${kpi('This week',inr(wk+640),'7%')}${kpi('Pending payout',inr(tot+780),'')}</div><div class="card pad stack"><h3>${t('Last 7 days')}</h3>${barChart(series('r1',7,300,420),lastDays(7),inr)}</div><div class="card pad stack"><h3>${t('How you earn')}</h3>${alertBox('info',`${t('Per ride')}: <b>${inr(D().cfg.riderBase)}</b> ${t('base')} + <b>${inr(D().cfg.riderPerKm)}/km</b>. ${t('Example: 3 km = ')}<b>${inr(riderEarn(3))}</b>.`)}</div><div class="card pad stack"><h3>${t('Payouts')}</h3>${tbl(['Week','Amount','Status'],[['Last week',inr(2840),`<span class="badge ok">${t('Paid')}</span>`],['This week',inr(wk+640+tot),`<span class="badge warn">${t('Pending')}</span>`]])}<div class="small muted">${t('Payout rules may change. Super Admin sets them.')}</div></div></div>`};
V.rfeedback=()=>{if(!canAct('rider'))return lockedMsg('rider');const l=D().reviews.filter(r=>r.tid===S.rider.rid);return `<div class="stack"><h1>${t('Feedback')}</h1><div class="card pad">${ratingBreak(l)}</div>${l.map(r=>revCard(r,'none')).join('')||empty('⭐','No feedback yet','Ratings from customers show here.')}</div>`};
V.rprofile=()=>{const r=rd();return `<div class="stack"><h1>${t('Profile & documents')}</h1>${gateNote('rider')}<form data-form="rprof" class="card pad stack">${field('Name','name',r.name,{req:1})}${field('Mobile','phone',r.phone,{type:'tel'})}${field('Vehicle','vehicle',r.vehicle)}<button class="btn p">${t('Save')}</button></form><div class="card pad stack"><h3>${t('Documents')}</h3>${[['Driving licence','approved'],['Aadhaar / ID','approved'],['RC book','approved'],['Selfie','approved']].map(([x,s])=>`<div class="row between"><span>${t(x)}</span>${apBadge(s)}</div>`).join('')}<button class="btn g sm" data-act="fakeUpload">${ic('upload',14)} ${t('Replace a document')}</button></div><div class="card pad stack"><h3>${t('Payout (UPI / bank)')}</h3>${field('UPI ID','upi','sunil@upi')}<button class="btn g sm" data-act="fakeUpload">${t('Update')}</button></div><div class="card pad row between"><span>${ic('globe',18)} ${t('Language')}</span><button class="btn g sm" data-act="lang">${S.lang==='en'?'हिन्दी':'English'}</button></div><div class="card pad stack"><h3>${t('Support & disputes')}</h3><form data-form="rdispute" class="stack">${field('Describe the issue','m','',{type:'textarea',req:1})}<button class="btn o">${t('Report to admin')}</button></form></div></div>`};
F.rprof=d=>{Object.assign(rd(),d);save();toast(t('Saved'))};F.rdispute=d=>{notify('admin','Rider dispute: '+rd().name,d.m.slice(0,70),'ahome','sys');save();render(true);toast(t('Sent to admin'),'send')};
/* rider signup */
UI.rw={step:1,d:{}};const RSTEPS=['Profile & photo','Vehicle','Documents','Payout details','Review'];
V.ronboard=()=>{const w=UI.rw,d=w.d;const nav=l=>`<div class="row"><button type="button" class="btn g" data-act="rprev" ${w.step===1?'disabled':''}>${t('Back')}</button><span class="grow"></span><button class="btn p">${l?t('Submit for approval'):t('Next')}</button></div>`;let b='';
 if(w.step===1)b=`<form data-form="rwiz" class="stack">${field('Full name','name',d.name||'',{req:1})}${field('Mobile number','phone',d.phone||'',{req:1,type:'tel',pattern:'[0-9]{10}'})}${uploader('Take a selfie')}${nav()}</form>`;
 if(w.step===2)b=`<form data-form="rwiz" class="stack">${field('Vehicle type','vtype',d.vtype||'Bike',{type:'select',opts:[['Bike','Bike'],['Scooter','Scooter'],['Cycle','Cycle']]})}${field('Vehicle number','vehicle',d.vehicle||'',{req:1})}${nav()}</form>`;
 if(w.step===3)b=`<form data-form="rwiz" class="stack">${['Driving licence','ID proof (Aadhaar)','RC book'].map(x=>`<div class="card pad row between"><span>${t(x)}</span><button type="button" class="btn g sm" data-act="fakeUpload">${ic('upload',14)} ${t('Upload')}</button></div>`).join('')}${nav()}</form>`;
 if(w.step===4)b=`<form data-form="rwiz" class="stack">${field('UPI ID','upi',d.upi||'',{req:1})}${field('Bank account (optional)','acc',d.acc||'')}${nav()}</form>`;
 if(w.step===5)b=`<form data-form="rwiz" class="stack"><div class="card pad"><dl class="kv"><dt>${t('Name')}</dt><dd>${esc(d.name)}</dd><dt>${t('Phone')}</dt><dd>${esc(d.phone)}</dd><dt>${t('Vehicle')}</dt><dd>${esc(d.vtype)} ${esc(d.vehicle)}</dd><dt>UPI</dt><dd>${esc(d.upi)}</dd></dl></div>${nav(true)}</form>`;
 return `<div class="stack" style="max-width:560px;margin:0 auto"><a class="btn t sm" href="#home" data-act="asRole" data-role="customer" style="justify-self:start">${ic('cl',16)} ${t('Exit')}</a><h1>${t('Become a rider')}</h1><div class="stack" style="gap:6px"><b class="small">${t('Step')} ${w.step} / ${RSTEPS.length}: ${t(RSTEPS[w.step-1])}</b><div class="progress"><i style="width:${w.step/RSTEPS.length*100}%"></i></div></div>${b}</div>`};
A.rprev=()=>{UI.rw.step=Math.max(1,UI.rw.step-1);render()};
F.rwiz=d=>{const w=UI.rw;Object.assign(w.d,d);if(w.step<RSTEPS.length){w.step++;render();return}const id='r'+(D().riders.length+1);D().riders.push({id,name:w.d.name,phone:w.d.phone,vehicle:w.d.vtype+' '+w.d.vehicle,rating:0,rc:0,online:false,status:'pending',area:'Padrauna'});D().apps.unshift({id:rid('ap'),type:'rider',name:w.d.name,owner:w.d.name,phone:w.d.phone,area:'Padrauna',ts:Date.now(),status:'pending',docs:['Driving licence','ID proof','RC book'],hist:[],ref:id});S.rider.rid=id;S.role='rider';notify('admin','New rider application',w.d.name,'aappr','appr');UI.rw={step:1,d:{}};save();sheet(`<div class="state"><div class="ill">🎉</div><h3>${t('Submitted for approval')}</h3><p>${t('We will verify your documents and notify you.')}</p><a class="btn p" href="#rhome" data-act="closeSheet">${t('Open rider app')}</a></div>`)};
